import XCTest

@testable import SongWorkbench

/// Numerical parity with torchaudio, against a fixture generated by the real transform.
///
/// The acoustic model learned these exact features, so "close enough" is not a thing here: a mel
/// that differs from training input produces a posteriorgram that is confidently wrong, and forced
/// alignment would then place words precisely at the wrong times. The fixture is produced by
/// `tools/lyrics_align_spike` from `torchaudio.transforms.MelSpectrogram(sample_rate: 22050,
/// n_mels: 128, n_fft: 512)`.
final class LyricsAlignmentMelTests: XCTestCase {
    private struct Reference: Decodable {
        let sampleRate: Double
        let nFFT: Int
        let hop: Int
        let nMels: Int
        let samples: [Float]
        /// `[mel][frame]`, torchaudio's layout.
        let mel: [[Float]]
    }

    private func loadReference() throws -> Reference {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/lyrics_alignment_mel_reference.json")
        try XCTSkipUnless(
            FileManager.default.fileExists(atPath: url.path), "mel reference fixture missing")
        return try JSONDecoder().decode(Reference.self, from: Data(contentsOf: url))
    }

    func testParametersMatchTheTrainedTransform() throws {
        let reference = try loadReference()
        XCTAssertEqual(LyricsAlignmentMel.sampleRate, reference.sampleRate)
        XCTAssertEqual(LyricsAlignmentMel.fftSize, reference.nFFT)
        XCTAssertEqual(LyricsAlignmentMel.hop, reference.hop)
        XCTAssertEqual(LyricsAlignmentMel.melBands, reference.nMels)
    }

    func testMatchesTorchaudioOnTheReferenceSignal() throws {
        let reference = try loadReference()
        let produced = LyricsAlignmentMel.spectrogram(samples: reference.samples)

        let expectedFrames = reference.mel[0].count
        XCTAssertEqual(produced.count, expectedFrames, "frame count")
        XCTAssertEqual(produced.first?.count, reference.mel.count, "mel band count")

        // Values span 0 ... ~3600, so compare relative to the reference's own scale.
        var worstRelative: Double = 0
        var worstDescription = ""
        let peak = reference.mel.flatMap { $0 }.map { abs($0) }.max() ?? 1
        for frame in 0..<min(produced.count, expectedFrames) {
            for band in 0..<reference.mel.count {
                let expected = reference.mel[band][frame]
                let actual = produced[frame][band]
                let relative = Double(abs(actual - expected)) / Double(peak)
                if relative > worstRelative {
                    worstRelative = relative
                    worstDescription = "band \(band) frame \(frame): \(actual) vs \(expected)"
                }
            }
        }
        XCTAssertLessThan(
            worstRelative, 1e-4,
            "mel differs from the trained transform — worst \(worstDescription)")
    }

    /// The transform returns magnitude SQUARED. A log or dB conversion slipped in anywhere would
    /// produce negative values and a completely different distribution.
    func testOutputIsPowerNotLog() throws {
        let reference = try loadReference()
        let produced = LyricsAlignmentMel.spectrogram(samples: reference.samples)
        XCTAssertFalse(produced.isEmpty)
        XCTAssertTrue(
            produced.allSatisfy { $0.allSatisfy { $0 >= 0 } },
            "power is non-negative; negatives mean a log crept in")
        XCTAssertGreaterThan(
            produced.flatMap { $0 }.max() ?? 0, 100,
            "power values are unbounded; a normalised or log scale would cap far lower")
    }

    /// `center: true` puts frame i at sample i*hop, giving 1 + n/hop frames.
    func testFrameCountFollowsCentredFraming() {
        for sampleCount in [2048, 4096, 11025] {
            let samples = (0..<sampleCount).map { Float(sin(Double($0) * 0.01)) }
            let produced = LyricsAlignmentMel.spectrogram(samples: samples)
            XCTAssertEqual(
                produced.count, 1 + sampleCount / LyricsAlignmentMel.hop,
                "frame count for \(sampleCount) samples")
        }
    }

    /// Empty filters are a property of 128 mels over 257 bins and are what the model trained on;
    /// "fixing" them by renormalising would change every feature it sees.
    func testFilterbankReproducesTheTrainedShapeIncludingDeadBands() {
        let bank = LyricsAlignmentMel.melFilterbank()
        XCTAssertEqual(bank.count, LyricsAlignmentMel.melBands)
        XCTAssertEqual(bank[0].count, LyricsAlignmentMel.fftSize / 2 + 1)
        XCTAssertTrue(bank.allSatisfy { $0.allSatisfy { $0 >= 0 && $0 <= 1 } })
        XCTAssertTrue(
            bank.contains { $0.allSatisfy { $0 == 0 } },
            "low bands are narrower than one FFT bin, so some come out all-zero — as in training")
        XCTAssertTrue(
            bank.suffix(40).allSatisfy { $0.contains { $0 > 0 } }, "high bands carry energy")
    }

    func testHannWindowIsPeriodic() {
        let window = LyricsAlignmentMel.hannPeriodic(8)
        // periodic: divides by n, so it never returns to 0 at the last sample
        XCTAssertEqual(window[0], 0, accuracy: 1e-6)
        XCTAssertEqual(window[4], 1, accuracy: 1e-6)
        XCTAssertGreaterThan(window[7], 0, "a symmetric window would end at 0")
    }
}
